"""Summarize the fixed V6 result and public-receipt complementarity evidence."""
import csv
import json
from pathlib import Path
import numpy as np

ROOT=Path(__file__).resolve().parents[1]


def main():
    scores=json.loads((ROOT/'results'/'holdout_scores.json').read_text())
    validation=json.loads((ROOT/'results'/'holdout_validation.json').read_text())
    mechanism=json.loads((ROOT/'results'/'holdout_globaldual_mechanism.json').read_text())
    rows=[]
    for r in scores['rows']:
        name=Path(r['file']).stem.split(r['case_id']+'_',1)[1]
        rows.append(dict(case_id=r['case_id'],method=name,top1_RMS=r['top1_RMS'],
                         top1_relative_residual=r['top1_relative_residual'],oracle_best_RMS=r['oracle_best_RMS'],
                         candidate_count=r['candidate_count'],data_accepted_count=r['data_accepted_count'],
                         numerical_wall_seconds=r['wall_seconds'],full_complex_rhs=r['cost']['full_complex_rhs'],
                         reduced_complex_rhs=r['cost']['reduced_complex_rhs'],
                         inner_QR=r['cost']['counts'].get('algebraic_QR',0),
                         algebraic_LS_RHS=r['cost']['counts'].get('algebraic_complex_rhs',0)))
    names=sorted(set(r['method'] for r in rows));summaries=[]
    for name in names:
        subset=[r for r in rows if r['method']==name]
        summaries.append(dict(method=name,cases=len(subset),
                              top1_data_fit_cases=sum(r['top1_relative_residual']<=1e-6 for r in subset),
                              mean_top1_RMS=float(np.mean([r['top1_RMS'] for r in subset])),
                              median_top1_RMS=float(np.median([r['top1_RMS'] for r in subset])),
                              mean_oracle_best_RMS=float(np.mean([r['oracle_best_RMS'] for r in subset])),
                              mean_numerical_wall_seconds=float(np.mean([r['numerical_wall_seconds'] for r in subset])),
                              total_full_complex_rhs=sum(r['full_complex_rhs'] for r in subset),
                              total_reduced_complex_rhs=sum(r['reduced_complex_rhs'] for r in subset),
                              total_algebraic_LS_RHS=sum(r['algebraic_LS_RHS'] for r in subset),
                              total_inner_QR=sum(r['inner_QR'] for r in subset)))
    complementary=[]
    for case in sorted(set(r['case_id'] for r in rows)):
        b=json.loads((ROOT/'results'/('holdout_'+case+'_FullJ1024.json')).read_text())
        g=json.loads((ROOT/'results'/('holdout_'+case+'_GlobalDual.json')).read_text())
        fit=b['fits'][0];candidate=b['candidates'][fit['candidate']]
        complementary.append(dict(case_id=case,FullJ_first_fit_relative_residual=candidate['relative_residual'],
                                  FullJ_first_fit_seconds=fit['wall_seconds'],
                                  FullJ_first_fit_started_seconds=fit['started_seconds'],
                                  FullJ_first_fit_available_seconds=fit['started_seconds']+fit['wall_seconds'],
                                  FullJ_first_fit_counts=fit['counts'],
                                  GlobalDual_top1_discovery_seconds=g['top1']['discovery_seconds'],
                                  GlobalDual_top1_relative_residual=g['top1']['relative_residual'],
                                  GlobalDual_residual_goal_first_seconds=next((v['seconds'] for v in g['best_so_far'] if v['relative_residual']<=1e-10),None)))
    result=dict(schema='R3_FROZEN_HOLDOUT_V6_SUMMARY',method_contract='experiments/HOLDOUT12_CONTRACT.json',
                prediction_freeze='audit/HOLDOUT_V6_FINAL_FREEZE.json',rows=rows,method_summaries=summaries,
                independent_all_candidate_validation=dict(candidates=sum(r['validated_count'] for r in validation['rows']),
                                                           all_pass=all(r['all_validated_pass'] for r in validation['rows']),
                                                           full_complex_rhs=validation['full_complex_rhs'],
                                                           maximum_stored_residual_disagreement=max(c.get('stored_residual_abs_disagreement',0) for r in validation['rows'] for c in r['rows'])),
                public_receipt_complementarity=complementary,
                interpretation='Mixed finite blind evidence. GlobalDual and reciprocal FullJ each fit2/4, with different successful cases. No dominance or general success claim. Novelty/support decision remains principal review; V6 HOLD preserved.',
                guard_pipeline='NOT_RUN; no additional target generated by this summary')
    (ROOT/'results'/'HOLDOUT_V6_SUMMARY.json').write_text(json.dumps(result,indent=2)+'\n')
    with (ROOT/'results'/'HOLDOUT_V6_METRICS.csv').open('w',newline='') as f:
        writer=csv.DictWriter(f,fieldnames=list(rows[0]));writer.writeheader();writer.writerows(rows)
    lines=['# Frozen V6 holdout result','','Four fresh targets; five frozen methods; maximum 3 s numerical wall per method/case. Top1 is selected by all-data residual before truth scoring. Oracle coverage is a separate offline diagnostic.','','| Method | Top1 data-fit cases (residual ≤ 1e-6) | Mean top1 RMS | Median top1 RMS | Mean oracle best RMS | Mean numerical s |','|---|---:|---:|---:|---:|---:|']
    for s in summaries:lines.append(f"| {s['method']} | {s['top1_data_fit_cases']}/4 | {s['mean_top1_RMS']:.6g} | {s['median_top1_RMS']:.6g} | {s['mean_oracle_best_RMS']:.6g} | {s['mean_numerical_wall_seconds']:.6g} |")
    lines.extend(['','GlobalDual succeeds on cases 00 and 03, fails on 01 and 02; reciprocal FullJ succeeds on 00 and 01. Native FullJ, coordinate and ABAR4 succeed only on 01. GlobalDual therefore does not dominate the reciprocal control. On case 02 its lower residual and better oracle coverage do not produce a recovered image. These four finite targets support complementarity observations, not global enumeration, an accepted general advantage, or a novelty claim. The V6 scientific disposition remains HOLD.','','All 3,500 archived candidates passed independent fresh NumPy full-VIE validation, at a cost of 10,500 additional full RHS. This validates physical evaluation and stored residuals; it does not upgrade unsuccessful reconstructions. Forty-nine raw dual endpoints that had merged with nearby archive candidates were additionally validated at 147 full RHS for exact phase analysis.','','## Pure dual endpoints and full-J corrections','','| Case | Pure endpoint residual top1 | Pure endpoint material RMS | Final residual top1 | Final top1 RMS | Endpoint full RHS | Correction full RHS | Inner QR / LS RHS |','|---|---:|---:|---:|---:|---:|---:|---:|'])
    for r in mechanism['rows']:
        raw=r['pure_endpoint_original_residual_top1'];inner=r['variable_projection_inner_cost']
        lines.append(f"| {r['case_id']} | {raw['relative_residual']:.6g} | {raw['material_RMS']:.6g} | {r['final_top1_relative_residual']:.6g} | {r['final_top1_RMS']:.6g} | {r['raw_endpoint_full_cost']['full_complex_rhs']} | {r['fullj_correction_cost']['full_complex_rhs']} | {inner['QR_factorizations']} / {inner['complex_LS_RHS']} |")
    lines.extend(['','Phase counts are exact for these frozen receipts: completed correction fit counters plus raw endpoint fees reproduce the total full cost. QR/LS work is charged separately. The dual objective is a proposal metric; all rankings in this table use the independently evaluated original-data residual.','','## Public-receipt complementarity audit','','These rows inspect existing public prediction receipts only. They do not run a guarded pipeline or reuse V6 targets as new blind evidence.','','| Case | Native FullJ first-start residual | First fit s | First fit available s | GlobalDual final top1 discovered s | GlobalDual goal reached |','|---|---:|---:|---:|---:|---|'])
    for r in complementary:lines.append(f"| {r['case_id']} | {r['FullJ_first_fit_relative_residual']:.6g} | {r['FullJ_first_fit_seconds']:.6g} | {r['FullJ_first_fit_available_seconds']:.6g} | {r['GlobalDual_top1_discovery_seconds']:.6g} | {'yes' if r['GlobalDual_residual_goal_first_seconds'] is not None else 'no'} |")
    lines.extend(['','No method was retuned after V6 truth scoring. `HOLDOUT_V6_METRICS.csv` preserves every case/method metric; `HOLDOUT_V6_SUMMARY.json` retains this summary plus first-fit operation counters. Complete paid exploration, setup, full/reduced/inner-LS work, independent validation and end-to-end subprocess time remain in `COST_LEDGER.json`.'])
    (ROOT/'results'/'HOLDOUT_V6_SUMMARY.md').write_text('\n'.join(lines)+'\n')
    print(json.dumps(summaries))


if __name__=='__main__':main()
